  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:shibuya-scramble-crossing', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Shibuya Scramble Crossing', 'attraction', 'The world''s busiest pedestrian intersection, where up to 3,000 people cross during a single green light cycle. It is a legendary symbol of modern Tokyo''s energetic urban life.', '[{"text": "For a bird''s-eye view of the crossing, visit the Shibuya Sky observation deck or the second-floor Starbucks in the Qfront building.", "source_url": "https://en.wikipedia.org/wiki/Shibuya_Crossing"}]'::jsonb, 'Open 24 hours', 'known', 'Shibuya Station', null, 35.6595, 139.70056, '1-2-1 Dogenzaka, Shibuya City, Tokyo 150-0043, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Shibuya_Crossing","https://www.gotokyo.org/en/spot/135/index.html"}', '{"name": "https://en.wikipedia.org/wiki/Shibuya_Crossing", "description": "https://en.wikipedia.org/wiki/Shibuya_Crossing", "hours": "https://www.gotokyo.org/en/spot/135/index.html", "station": "https://en.wikipedia.org/wiki/Shibuya_Crossing", "lat": "https://en.wikipedia.org/wiki/Shibuya_Crossing", "lng": "https://en.wikipedia.org/wiki/Shibuya_Crossing", "address": "https://www.gotokyo.org/en/spot/135/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/c/c5/Tokyo_Shibuya_Scramble_Crossing_2018-10-09.jpg", "credit": "Benh LIEU SONG (Flickr)", "license": "CC BY-SA 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Tokyo_Shibuya_Scramble_Crossing_2018-10-09.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/8/88/Shibuya_Crossing%2C_Aerial.jpg", "credit": "David Kernan", "license": "CC BY 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Shibuya_Crossing,_Aerial.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:hachiko-statue', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Hachiko Statue', 'attraction', 'A famous bronze statue of the loyal Akita dog Hachiko, who waited for his deceased master daily at Shibuya Station for nearly ten years. It serves as Shibuya''s most iconic meeting point.', '[{"text": "The statue is a highly popular meeting spot and can get very crowded, so mornings are best for photos without crowds.", "source_url": "https://en.wikipedia.org/wiki/Hachik%C5%8D"}]'::jsonb, 'Open 24 hours', 'known', 'Shibuya Station', null, 35.65908, 139.70058, '2-1 Dogenzaka, Shibuya City, Tokyo 150-0043, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Hachik%C5%8D","https://www.gotokyo.org/en/spot/135/index.html"}', '{"name": "https://en.wikipedia.org/wiki/Hachik%C5%8D", "description": "https://en.wikipedia.org/wiki/Hachik%C5%8D", "hours": "https://www.gotokyo.org/en/spot/135/index.html", "station": "https://en.wikipedia.org/wiki/Hachik%C5%8D", "lat": "https://en.wikipedia.org/wiki/Hachik%C5%8D", "lng": "https://en.wikipedia.org/wiki/Hachik%C5%8D", "address": "https://www.gotokyo.org/en/spot/135/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/5/53/Hachiko_%2853083712909%29.jpg", "credit": "Dick Thomas Johnson from Tokyo, Japan", "license": "CC BY 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Hachiko_(53083712909).jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/d/d9/1RAR_soldiers_on_leave_in_Tokyo_with_Hachiko_statue.jpg", "credit": "Meldrum, Donald Albert (Tim)", "license": "Public domain", "source_url": "https://commons.wikimedia.org/wiki/File:1RAR_soldiers_on_leave_in_Tokyo_with_Hachiko_statue.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:shibuya-sky', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Shibuya Sky', 'viewpoint', 'A spectacular open-air observation deck on the roof of the Shibuya Scramble Square skyscraper, offering 360-degree panoramic views of Tokyo including Mount Fuji.', '[{"text": "Tickets are cheaper when purchased online in advance, and you must book a specific time slot, with sunset hours being the most popular and selling out quickly.", "source_url": "https://en.wikipedia.org/wiki/Shibuya_Scramble_Square"}]'::jsonb, '10:00 AM - 10:30 PM', 'known', 'Shibuya Station', null, 35.6585, 139.7018, '2-24-12 Shibuya, Shibuya City, Tokyo 150-6101, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Shibuya_Scramble_Square","https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}', '{"name": "https://en.wikipedia.org/wiki/Shibuya_Scramble_Square", "description": "https://en.wikipedia.org/wiki/Shibuya_Scramble_Square", "hours": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html", "station": "https://en.wikipedia.org/wiki/Shibuya_Scramble_Square", "lat": "https://en.wikipedia.org/wiki/Shibuya_Scramble_Square", "lng": "https://en.wikipedia.org/wiki/Shibuya_Scramble_Square", "address": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/4/45/SHIBUYA_SCRAMBLE_SQUARE_East_Tower.jpg", "credit": "Sakura Torch", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:SHIBUYA_SCRAMBLE_SQUARE_East_Tower.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/1/10/Shibuya_Scramble_Square_2.jpg", "credit": "Syced", "license": "CC0", "source_url": "https://commons.wikimedia.org/wiki/File:Shibuya_Scramble_Square_2.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:yoyogi-park', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Yoyogi Park', 'park', 'One of Tokyo''s largest and most popular public parks, known for its spacious lawns, ginkgo forests, and lively weekend gatherings of musicians and street performers.', '[{"text": "The park is especially famous for street performers, musicians, and subculture gatherings on Sundays.", "source_url": "https://en.wikipedia.org/wiki/Yoyogi_Park"}]'::jsonb, 'Open 24 hours', 'known', 'Harajuku Station', null, 35.6716, 139.6949, '2-1 Yoyogikamizonocho, Shibuya City, Tokyo 151-0052, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Yoyogi_Park","https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}', '{"name": "https://en.wikipedia.org/wiki/Yoyogi_Park", "description": "https://en.wikipedia.org/wiki/Yoyogi_Park", "hours": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html", "station": "https://en.wikipedia.org/wiki/Yoyogi_Park", "lat": "https://en.wikipedia.org/wiki/Yoyogi_Park", "lng": "https://en.wikipedia.org/wiki/Yoyogi_Park", "address": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/c/c5/Mainstreet_Yoyogipark.JPG", "credit": "Shinjiro", "license": "CC BY 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Mainstreet_Yoyogipark.JPG", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/7/78/Yoyogi_Park_-_panoramio_%282%29.jpg", "credit": "kcomiida", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Yoyogi_Park_-_panoramio_(2).jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:meiji-jingu', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Meiji Jingu', 'shrine', 'A peaceful and majestic Shinto shrine dedicated to the deified spirits of Emperor Meiji and Empress Shoken, situated within a dense forest of over 100,000 trees.', '[{"text": "The shrine hours change monthly according to sunrise and sunset times, so verify the exact hours before visiting.", "source_url": "https://en.wikipedia.org/wiki/Meiji_Shrine"}]'::jsonb, '5:00 AM - 6:00 PM', 'known', 'Harajuku Station', null, 35.6763, 139.6993, '1-1 Yoyogikamizonocho, Shibuya City, Tokyo 151-8557, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Meiji_Shrine","https://www.gotokyo.org/en/spot/54/index.html"}', '{"name": "https://en.wikipedia.org/wiki/Meiji_Shrine", "description": "https://en.wikipedia.org/wiki/Meiji_Shrine", "hours": "https://www.gotokyo.org/en/spot/54/index.html", "station": "https://en.wikipedia.org/wiki/Meiji_Shrine", "lat": "https://en.wikipedia.org/wiki/Meiji_Shrine", "lng": "https://en.wikipedia.org/wiki/Meiji_Shrine", "address": "https://www.gotokyo.org/en/spot/54/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/e/ed/Courtyard_of_Meiji_Shrine_20190717.jpg", "credit": "Tokuzo in Edomura", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Courtyard_of_Meiji_Shrine_20190717.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/f/fc/Meiji-jingu_Torii_1.jpg", "credit": "Zairon", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Meiji-jingu_Torii_1.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:nonbei-yokocho', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Nonbei Yokocho', 'nightlife', 'A charming, narrow alleyway dating back to the post-war era, packed with tiny, historic bars that offer an authentic glimpse into old-school Tokyo nightlife.', '[{"text": "Most bars in this historic alleyway are tiny, seating only 4-5 people, and many charge a small table cover fee (otōshi).", "source_url": "https://en.wikipedia.org/wiki/Shibuya"}]'::jsonb, '5:00 PM - midnight', 'known', 'Shibuya Station', null, 35.6599, 139.7015, '1-25-10 Shibuya, Shibuya City, Tokyo 150-0002, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Shibuya","https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}', '{"name": "https://en.wikipedia.org/wiki/Shibuya", "description": "https://en.wikipedia.org/wiki/Shibuya", "hours": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html", "station": "https://en.wikipedia.org/wiki/Shibuya", "lat": "https://en.wikipedia.org/wiki/Shibuya", "lng": "https://en.wikipedia.org/wiki/Shibuya", "address": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/e/e7/Shibuya_Nonbei_Yokocho_%2853085175407%29.jpg", "credit": "Dick Thomas Johnson from Tokyo, Japan", "license": "CC BY 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Shibuya_Nonbei_Yokocho_(53085175407).jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/a/a4/Shibuya_Nonbei_Yokocho_%2853330131727%29.jpg", "credit": "Dick Thomas Johnson from Tokyo, Japan", "license": "CC BY 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Shibuya_Nonbei_Yokocho_(53330131727).jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:cat-street', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Cat Street', 'shopping-street', 'A leafy, pedestrian-friendly shopping street that serves as the creative epicenter of Tokyo street fashion, connecting Harajuku and Shibuya with unique boutiques and cafes.', '[{"text": "Cat Street is the center of Tokyo''s street fashion culture, linking Shibuya and Harajuku with unique boutiques and cafes.", "source_url": "https://en.wikipedia.org/wiki/Cat_Street,_Tokyo"}]'::jsonb, 'Open 24 hours', 'known', 'Meiji-Jingumae Station', null, 35.6644, 139.7042, 'Jingumae, Shibuya City, Tokyo 150-0001, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Cat_Street,_Tokyo","https://www.gotokyo.org/en/spot/544/index.html"}', '{"name": "https://en.wikipedia.org/wiki/Cat_Street,_Tokyo", "description": "https://en.wikipedia.org/wiki/Cat_Street,_Tokyo", "hours": "https://www.gotokyo.org/en/spot/544/index.html", "station": "https://en.wikipedia.org/wiki/Cat_Street,_Tokyo", "lat": "https://en.wikipedia.org/wiki/Cat_Street,_Tokyo", "lng": "https://en.wikipedia.org/wiki/Cat_Street,_Tokyo", "address": "https://www.gotokyo.org/en/spot/544/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/9/92/Cat_Street_in_Tokyo%2C_2019_-_799.jpg", "credit": "Another Believer", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Cat_Street_in_Tokyo,_2019_-_799.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/d/db/Decoration_in_Cat_Street%2C_Tokyo.jpg", "credit": "Syced", "license": "CC0", "source_url": "https://commons.wikimedia.org/wiki/File:Decoration_in_Cat_Street,_Tokyo.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:miyashita-park', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Miyashita Park', 'park', 'A modern, multi-level park and commercial complex that features a rooftop green space with athletic facilities, trendy shops, and a lively food alley.', '[{"text": "This multi-story complex features a rooftop park with a bouldering wall, skateboard park, and sand volleyball court alongside upscale shopping.", "source_url": "https://en.wikipedia.org/wiki/Miyashita_Park"}]'::jsonb, '8:00 AM - 11:00 PM', 'known', 'Shibuya Station', null, 35.6616, 139.7022, '1-26-5 Shibuya, Shibuya City, Tokyo 150-0002, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Miyashita_Park","https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}', '{"name": "https://en.wikipedia.org/wiki/Miyashita_Park", "description": "https://en.wikipedia.org/wiki/Miyashita_Park", "hours": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html", "station": "https://en.wikipedia.org/wiki/Miyashita_Park", "lat": "https://en.wikipedia.org/wiki/Miyashita_Park", "lng": "https://en.wikipedia.org/wiki/Miyashita_Park", "address": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/9/91/Miyashita_Park_on_a_sunny_day_19.jpg", "credit": "Syced", "license": "CC0", "source_url": "https://commons.wikimedia.org/wiki/File:Miyashita_Park_on_a_sunny_day_19.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/2/26/Miyashita_Park_200802j.jpg", "credit": "江戸村のとくぞう", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Miyashita_Park_200802j.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:shibuya-center-gai', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Shibuya Center-Gai', 'shopping-street', 'A bustling pedestrian street and the vibrant heart of youth culture in Shibuya, lined with a dense array of fashion boutiques, game centers, and restaurants.', '[{"text": "This busy pedestrian street is packed with shops, game centers, fast food joints, and bars, making it highly lively at night.", "source_url": "https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC%E8%A1%97"}]'::jsonb, 'Open 24 hours', 'known', 'Shibuya Station', null, 35.6601, 139.6994, 'Udagawacho, Shibuya City, Tokyo 150-0042, Japan', null, null, null, '{}', '{"https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC%E8%A1%97","https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}', '{"name": "https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC%E8%A1%97", "description": "https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC%E8%A1%97", "hours": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html", "station": "https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC%E8%A1%97", "lat": "https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC%E8%A1%97", "lng": "https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC%E8%A1%97", "address": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/f/f7/%E6%B8%8B%E8%B0%B7%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC%E8%A1%97_2026%E5%B9%B46%E6%9C%881%E6%97%A5%E3%81%AE%E6%B8%8B%E8%B0%B7_202606011451_IMG_7759.jpg", "credit": "ウィ貴公子", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:%E6%B8%8B%E8%B0%B7%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC%E8%A1%97_2026%E5%B9%