  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:konnoh-hachimangu', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Konnoh Hachimangu', 'shrine', 'An ancient Shinto shrine established in 1092, featuring historic wooden architecture that survived the air raids of World War II and beautiful seasonal cherry blossoms.', '[{"text": "This historic shrine has deep roots with the Shibuya clan, and its grounds contain remnants of Shibuya Castle.", "source_url": "https://ja.wikipedia.org/wiki/%E9%87%91%E7%8E%8B%E5%85%AB%E5%B9%A1%E5%AE%AE"}]'::jsonb, 'Open 24 hours', 'known', 'Shibuya Station', null, 35.6565, 139.7058, '3-5-12 Shibuya, Shibuya City, Tokyo 150-0002, Japan', null, null, null, '{}', '{"https://ja.wikipedia.org/wiki/%E9%87%91%E7%8E%8B%E5%85%AB%E5%B9%A1%E5%AE%AE","https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}', '{"name": "https://ja.wikipedia.org/wiki/%E9%87%91%E7%8E%8B%E5%85%AB%E5%B9%A1%E5%AE%AE", "description": "https://ja.wikipedia.org/wiki/%E9%87%91%E7%8E%8B%E5%85%AB%E5%B9%A1%E5%AE%AE", "hours": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html", "station": "https://ja.wikipedia.org/wiki/%E9%87%91%E7%8E%8B%E5%85%AB%E5%B9%A1%E5%AE%AE", "lat": "https://ja.wikipedia.org/wiki/%E9%87%91%E7%8E%8B%E5%85%AB%E5%B9%A1%E5%AE%AE", "lng": "https://ja.wikipedia.org/wiki/%E9%87%91%E7%8E%8B%E5%85%AB%E5%B9%A1%E5%AE%AE", "address": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/3/3b/Konno-hachimangu%2C_keidai.jpg", "credit": "Saigen Jiro", "license": "CC0", "source_url": "https://commons.wikimedia.org/wiki/File:Konno-hachimangu,_keidai.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/0/04/Sangaku_of_Konnoh_Hachimangu_1850.jpg", "credit": "Momotarou2012", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Sangaku_of_Konnoh_Hachimangu_1850.jpg", "is_