  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:toguri-museum-of-art', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Toguri Museum of Art', 'museum', 'A specialized museum in the quiet Shoto residential area, dedicated to the preservation and exhibition of exquisite East Asian ceramic art and porcelain.', '[{"text": "The museum is one of the few in the world specializing in East Asian ceramics, with a rich collection of Imari and Nabeshima porcelain.", "source_url": "https://en.wikipedia.org/wiki/Toguri_Museum"}]'::jsonb, '10:00 AM - 5:00 PM', 'known', 'Shibuya Station', null, 35.6612, 139.6937, '1-11-3 Shoto, Shibuya City, Tokyo 150-0046, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Toguri_Museum","https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}', '{"name": "https://en.wikipedia.org/wiki/Toguri_Museum", "description": "https://en.wikipedia.org/wiki/Toguri_Museum", "hours": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html", "station": "https://en.wikipedia.org/wiki/Toguri_Museum", "lat": "https://en.wikipedia.org/wiki/Toguri_Museum", "lng": "https://en.wikipedia.org/wiki/Toguri_Museum", "address": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/3/34/Toguri_Museum_of_Art_2010.jpg", "credit": "Asanagi (talk)", "license": "Public domain", "source_url": "https://commons.wikimedia.org/wiki/File:Toguri_Museum_of_Art_2010.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/d/df/Toguri_Museum_of_Art_-_Shibuya%2C_Tokyo%2C_Japan_-_DSC09958.jpg", "credit": "Daderot", "license": "CC0", "source_url": "https://commons.wikimedia.org/wiki/File:Toguri_Museum_of_Art_-_Shibuya,_Tokyo,_Japan_-_DSC09958.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:shoto-museum-of-art', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Shoto Museum of Art', 'museum', 'A public art museum featuring a striking architectural design by Seiichi Shirai, hosting diverse exhibitions of painting, sculpture, and local crafts.', '[{"text": "Designed by the notable architect Shirai Seiichi, the building itself is an architectural masterpiece featuring a central fountain court.", "source_url": "https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E5%8C%BA%E7%AB%8B%E6%9D%BE%E6%BF%A4%E7%BE%8E%E8%A1%93%E9%A4%A8"}]'::jsonb, '10:00 AM - 5:00 PM', 'known', 'Shinsen Station', null, 35.6602, 139.6917, '2-14-14 Shoto, Shibuya City, Tokyo 150-0046, Japan', null, null, null, '{}', '{"https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E5%8C%BA%E7%AB%8B%E6%9D%BE%E6%BF%A4%E7%BE%8E%E8%A1%93%E9%A4%A8","https://www.gotokyo.org/en/spot/99/index.html"}', '{"name": "https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E5%8C%BA%E7%AB%8B%E6%9D%BE%E6%BF%A4%E7%BE%8E%E8%A1%93%E9%A4%A8", "description": "https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E5%8C%BA%E7%AB%8B%E6%9D%BE%E6%BF%A4%E7%BE%8E%E8%A1%93%E9%A4%A8", "hours": "https://www.gotokyo.org/en/spot/99/index.html", "station": "https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E5%8C%BA%E7%AB%8B%E6%9D%BE%E6%BF%A4%E7%BE%8E%E8%A1%93%E9%A4%A8", "lat": "https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E5%8C%BA%E7%AB%8B%E6%9D%BE%E6%BF%A4%E7%BE%8E%E8%A1%93%E9%A4%A8", "lng": "https://ja.wikipedia.org/wiki/%E6%B8%8B%E8%B0%B7%E5%8C%BA%E7%AB%8B%E6%9D%BE%E6%BF%A4%E7%BE%8E%E8%A1%93%E9%A4%A8", "address": "https://www.gotokyo.org/en/spot/99/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/0/0c/Shoto_Museum_of_Art_2010.jpg", "credit": "Wiiii", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Shoto_Museum_of_Art_2010.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/2/29/Shot