  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:shibuya-hikarie', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Shibuya Hikarie', 'shopping-street', 'A landmark high-rise commercial complex featuring a major theater, trendy fashion floors, and an 11th-floor sky lobby with panoramic city views.', '[{"text": "Head to Sky Lobby on the 11th floor for a great, free panoramic view of the Shibuya district.", "source_url": "https://en.wikipedia.org/wiki/Shibuya_Hikarie"}]'::jsonb, '11:00 AM - 9:00 PM', 'known', 'Shibuya Station', null, 35.659, 139.7034, '2-21-1 Shibuya, Shibuya City, Tokyo 150-8510, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Shibuya_Hikarie","https://www.gotokyo.org/en/spot/513/index.html"}', '{"name": "https://en.wikipedia.org/wiki/Shibuya_Hikarie", "description": "https://en.wikipedia.org/wiki/Shibuya_Hikarie", "hours": "https://www.gotokyo.org/en/spot/513/index.html", "station": "https://en.wikipedia.org/wiki/Shibuya_Hikarie", "lat": "https://en.wikipedia.org/wiki/Shibuya_Hikarie", "lng": "https://en.wikipedia.org/wiki/Shibuya_Hikarie", "address": "https://www.gotokyo.org/en/spot/513/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/a/a9/Shibuya_Hikarie_2.jpg", "credit": "Syced", "license": "CC0", "source_url": "https://commons.wikimedia.org/wiki/File:Shibuya_Hikarie_2.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/9/91/Shibuya_Hikarie_%E2%85%A1.JPG", "credit": "Kakidai", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Shibuya_Hikarie_%E2%85%A1.JPG", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:log-road-daikanyama', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Log Road Daikanyama', 'scenic-walk', 'A peaceful, wooden-decked walking path built on the former tracks of the Tokyu Toyoko Line, featuring stylish craft beer venues and chic apparel shops.', '[{"text": "Built on the former tracks of the Tokyu Toyoko Line, this pleasant, leafy promenade features boutique shops and microbreweries.", "source_url": "https://ja.wikipedia.org/wiki/LOG_ROAD_DAIKANYAMA"}]'::jsonb, '9:00 AM - 10:00 PM', 'known', 'Daikanyama Station', null, 35.6521, 139.7049, '13-1 Daikanyamacho, Shibuya City, Tokyo 150-0034, Japan', null, null, null, '{}', '{"https://ja.wikipedia.org/wiki/LOG_ROAD_DAIKANYAMA","https://www.gotokyo.org/en/destinations/western-tokyo/daikanyama/index.html"}', '{"name": "https://ja.wikipedia.org/wiki/LOG_ROAD_DAIKANYAMA", "description": "https://ja.wikipedia.org/wiki/LOG_ROAD_DAIKANYAMA", "hours": "https://www.gotokyo.org/en/destinations/western-tokyo/daikanyama/index.html", "station": "https://ja.wikipedia.org/wiki/LOG_ROAD_DAIKANYAMA", "lat": "https://ja.wikipedia.org/wiki/LOG_ROAD_DAIKANYAMA", "lng": "https://ja.wikipedia.org/wiki/LOG_ROAD_DAIKANYAMA", "address": "https://www.gotokyo.org/en/destinations/western-tokyo/daikanyama/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/3/39/LOG_ROAD_DAIKANYAMA_overview_2018.jpg", "credit": "Wpcpey", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:LOG_ROAD_DAIKANYAMA_overview_2018.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/a/a3/LOG_ROAD_DAIKANYAMA_pathway_2018.jpg", "credit": "Wpcpey", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:LOG_ROAD_DAIKANYAMA_pathway_2018.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+0