  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:nabeshima-shoto-park', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Nabeshima Shoto Park', 'park', 'A tranquil neighborhood park in Shoto, known for its picturesque pond, traditional wooden waterwheel, and cherry blossoms that bloom beautifully in spring.', '[{"text": "A peaceful park in the upscale Shoto residential area, famous for its picturesque pond and traditional wooden waterwheel.", "source_url": "https://ja.wikipedia.org/wiki/%E9%8D%8B%E5%B3%B6%E6%9D%BE%E6%BF%A4%E5%85%AC%E5%9C%92"}]'::jsonb, 'Open 24 hours', 'known', 'Shinsen Station', null, 35.6619, 139.6911, '2-10-7 Shoto, Shibuya City, Tokyo 150-0046, Japan', null, null, null, '{}', '{"https://ja.wikipedia.org/wiki/%E9%8D%8B%E5%B3%B6%E6%9D%BE%E6%BF%A4%E5%85%AC%E5%9C%92","https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}', '{"name": "https://ja.wikipedia.org/wiki/%E9%8D%8B%E5%B3%B6%E6%9D%BE%E6%BF%A4%E5%85%AC%E5%9C%92", "description": "https://ja.wikipedia.org/wiki/%E9%8D%8B%E5%B3%B6%E6%9D%BE%E6%BF%A4%E5%85%AC%E5%9C%92", "hours": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html", "station": "https://ja.wikipedia.org/wiki/%E9%8D%8B%E5%B3%B6%E6%9D%BE%E6%BF%A4%E5%85%AC%E5%9C%92", "lat": "https://ja.wikipedia.org/wiki/%E9%8D%8B%E5%B3%B6%E6%9D%BE%E6%BF%A4%E5%85%AC%E5%9C%92", "lng": "https://ja.wikipedia.org/wiki/%E9%8D%8B%E5%B3%B6%E6%9D%BE%E6%BF%A4%E5%85%AC%E5%9C%92", "address": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/3/31/Nabeshima_shoutou_park_shibuya.JPG", "credit": "Kamemaru2000", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Nabeshima_shoutou_park_shibuya.JPG", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/8/80/Nabeshima_Shoto_park_%2873046%29.jpg", "credit": "Syced", "license": "CC0", "source_url": "https://commons.wik