  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:kairyou-yu', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Kairyou-yu', 'bath', 'A stylish, century-old public bathhouse (sento) that was beautifully renovated in 2018 with contemporary design elements, neon lights, and relaxing saunas.', '[{"text": "A designer public bathhouse (sento) dating from 1916 and stylishly renovated, featuring a whale mural, neon lights, and saunas.", "source_url": "https://ja.wikipedia.org/wiki/%E6%94%B9%E8%89%AF%E6%B9%AF"}]'::jsonb, '12:00 PM - 11:30 PM', 'known', 'Shibuya Station', null, 35.6536, 139.7081, '2-19-9 Higashi, Shibuya City, Tokyo 150-0011, Japan', null, null, null, '{}', '{"https://ja.wikipedia.org/wiki/%E6%94%B9%E8%89%AF%E6%B9%AF","https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}', '{"name": "https://ja.wikipedia.org/wiki/%E6%94%B9%E8%89%AF%E6%B9%AF", "description": "https://ja.wikipedia.org/wiki/%E6%94%B9%E8%89%AF%E6%B9%AF", "hours": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html", "station": "https://ja.wikipedia.org/wiki/%E6%94%B9%E8%89%AF%E6%B9%AF", "lat": "https://ja.wikipedia.org/wiki/%E6%94%B9%E8%89%AF%E6%B9%AF", "lng": "https://ja.wikipedia.org/wiki/%E6%94%B9%E8%89%AF%E6%B9%AF", "address": "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"}'::jsonb, null, '[]'::jsonb, 'gemini-3.5-flash', 'approved', '["no verifiable image"]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shibuya:farmer-s-market-unu', 'Kanto', 'Tokyo', 'Shibuya', 'JP', 'Farmer''s Market @ UNU', 'market', 'A popular weekend open-air market held in front of the United Nations University, showcasing organic produce, artisanal goods, and delicious food trucks.', '[{"text": "Held every Saturday and Sunday in the courtyard of the United Nations University, it features local organic produce and artisanal food trucks.", "source_url": "https://ja.wikipedia.org/wiki/%E5%9B%BD%E9%80%A3%E5%A4%A7%E5%AD%A6"}]'::jsonb, '10:00 AM - 4:00 PM', 'known', 'Omotesando Station', null, 35.6622, 139.7077, '5-53-70 Jingumae, Shibuya City, Tokyo 150-0001, Japan', null, null, null, '{}', '{"https://ja.wikipedia.org/wiki/%E5%9B%BD%E9%80%A3%E5%A4%A7%E5%AD%A6","https://www.gotokyo.org/en/destinations/western-tokyo/harajuku/index.html"}', '{"name": "https://ja.wikipedia.org/wiki/%E5%9B%BD%E9%80%A3%E5%A4%A7%E5%AD%A6", "description": "https://ja.wikipedia.org/wiki/%E5%9B%BD%E9%80%A3%E5%A4%A7%E5%AD%A6", "hours": "https://www.gotokyo.org/en/destinations/western-tokyo/harajuku/index.html", "station": "https://ja.wikipedia.org/wiki/%E5%9B%BD%E9%80%A3%E5%A4%A7%E5%AD%A6", "lat": "https://ja.wikipedia.org/wiki/%E5%9B%BD%E9%80%A3%E5%A4%A7%E5%AD%A6", "lng": "https://ja.wikipedia.org/wiki/%E5%9B%BD%E9%80%A3%E5%A4%A7%E5%AD%A6", "address": "https://www.gotokyo.org/en/destinations/western-tokyo/harajuku/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/3/32/United-Nations-University-03.jpg", "credit": "Rs1421", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:United-Nations-University-03.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/4/4f/United_Nations_University_Tokyo_2018.jpg", "credit": "Ubahnverleih", "license": "CC0", "source_url": "https://commons.wikimedia.org/wiki/File:United_Nations_University_Tokyo_2018.jpg", "is_exact_place": true, 