  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:shinjuku-gyoen-national-garden', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Shinjuku Gyoen National Garden', 'park', 'A magnificent national garden that seamlessly blends traditional Japanese, formal French, and landscape English garden styles across extensive lawns and ponds.', '[{"text": "Check out the traditional greenhouse which houses over 2,700 species of tropical and subtropical plants.", "source_url": "https://www.env.go.jp/garden/shinjukugyoen/english/2_guide/guide.html"}]'::jsonb, '9:00 AM - 4:30 PM', 'known', 'Shinjuku-gyoemmae Station', null, 35.68716944444444, 139.71064444444445, '11 Naito-machi, Shinjuku-ku, Tokyo 160-0014', null, null, null, '{}', '{"https://www.env.go.jp/garden/shinjukugyoen/english/index.html","https://www.env.go.jp/garden/shinjukugyoen/english/2_guide/guide.html","https://en.wikipedia.org/wiki/Shinjuku_Gyo-en"}', '{"name": "https://en.wikipedia.org/wiki/Shinjuku_Gyo-en", "description": "https://en.wikipedia.org/wiki/Shinjuku_Gyo-en", "hours": "https://www.env.go.jp/garden/shinjukugyoen/english/2_guide/guide.html", "station": "https://www.env.go.jp/garden/shinjukugyoen/english/2_guide/guide.html", "lat": "https://en.wikipedia.org/wiki/Shinjuku_Gyo-en", "lng": "https://en.wikipedia.org/wiki/Shinjuku_Gyo-en", "address": "https://www.env.go.jp/garden/shinjukugyoen/english/2_guide/guide.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/1/15/2018-09-23_trees_in_Shinjuku_Gyo-en.jpg", "credit": "Sergey Galyonkin", "license": "CC BY-SA 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:2018-09-23_trees_in_Shinjuku_Gyo-en.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/f/fe/A_path_from_the_greenhouse_in_Shinjuku_Gyoen_National_Garden_in_Shinjuku%2C_Tokyo%2C_Japan%2C_2024_May.jpg", "credit": "Ximonic (Simo Räsänen)", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:A_