  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:tokyo-metropolitan-government-building-observation-deck', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Tokyo Metropolitan Government Building Observation Deck', 'viewpoint', 'Free, panoramic observation decks located on the 45th floor of the Tokyo Metropolitan Government Building, offering spectacular views of Tokyo and Mount Fuji on clear days.', '[{"text": "The North Observation Deck features a cafe and gift shop and remains open later into the evening.", "source_url": "https://www.yokoso.metro.tokyo.lg.jp/en/tenbou/index.html"}]'::jsonb, '9:30 AM - 10:00 PM', 'known', 'Tocho-mae Station', null, 35.68951, 139.69171, '2-8-1 Nishi-Shinjuku, Shinjuku-ku, Tokyo 163-8001', null, null, null, '{}', '{"https://www.yokoso.metro.tokyo.lg.jp/en/tenbou/index.html","https://en.wikipedia.org/wiki/Tokyo_Metropolitan_Government_Building"}', '{"name": "https://en.wikipedia.org/wiki/Tokyo_Metropolitan_Government_Building", "description": "https://en.wikipedia.org/wiki/Tokyo_Metropolitan_Government_Building", "hours": "https://www.yokoso.metro.tokyo.lg.jp/en/tenbou/index.html", "station": "https://www.yokoso.metro.tokyo.lg.jp/en/tenbou/index.html", "lat": "https://en.wikipedia.org/wiki/Tokyo_Metropolitan_Government_Building", "lng": "https://en.wikipedia.org/wiki/Tokyo_Metropolitan_Government_Building", "address": "https://www.yokoso.metro.tokyo.lg.jp/en/tenbou/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/a/af/Around_Shinjuku_11.jpg", "credit": "Syced", "license": "CC0", "source_url": "https://commons.wikimedia.org/wiki/File:Around_Shinjuku_11.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/5/52/Around_Shinjuku_14.jpg", "credit": "Syced", "license": "CC0", "source_url": "https://commons.wikimedia.org/wiki/File:Around_Shinjuku_14.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:omoide-yokocho', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Omoide Yokocho', 'food', 'A narrow, rustic alleyway located near Shinjuku Station''s west exit, packed with tiny, open-front eateries serving yakitori, motsuyaki, and drinks.', '[{"text": "Most stalls have a very small capacity of 5 to 10 seats, so be prepared to wait or move along quickly once finished.", "source_url": "http://shinjuku-omoide.com/english/index.html"}]'::jsonb, 'unknown', 'unknown', 'Shinjuku Station', null, 35.69307, 139.6995, '1-1-1 Nishi-Shinjuku, Shinjuku-ku, Tokyo 160-0023', null, null, null, '{}', '{"http://shinjuku-omoide.com/english/index.html","https://ja.wikipedia.org/wiki/%E6%96%B0%E5%AE%BF%E8%A5%BF%E5%8F%A3%E5%95%86%E5%BA%97%E8%A1%97"}', '{"name": "https://ja.wikipedia.org/wiki/%E6%96%B0%E5%AE%BF%E8%A5%BF%E5%8F%A3%E5%95%86%E5%BA%97%E8%A1%97", "description": "https://ja.wikipedia.org/wiki/%E6%96%B0%E5%AE%BF%E8%A5%BF%E5%8F%A3%E5%95%86%E5%BA%97%E8%A1%97", "station": "http://shinjuku-omoide.com/english/index.html", "lat": "https://ja.wikipedia.org/wiki/%E6%96%B0%E5%AE%BF%E8%A5%BF%E5%8F%A3%E5%95%86%E5%BA%97%E8%A1%97", "lng": "https://ja.wikipedia.org/wiki/%E6%96%B0%E5%AE%BF%E8%A5%BF%E5%8F%A3%E5%95%86%E5%BA%97%E8%A1%97", "address": "http://shinjuku-omoide.com/english/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/1/1c/20200605_105508%E8%A5%BF%E6%96%B0%E5%AE%BF%E3%83%BB%E6%80%9D%E3%81%84%E5%87%BA%E6%A8%AA%E4%B8%81.jpg", "credit": "Bject", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:20200605_105508%E8%A5%BF%E6%96%B0%E5%AE%BF%E3%83%BB%E6%80%9D%E3%81%84%E5%87%BA%E6%A8%AA%E4%B8%81.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/b/b8/Japan_-_Tokyo_-_Shinjuku_Area.jpg", "credit": "Vanvelthem Cédric", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Japan_-_Tokyo_-_Shinjuku_Area.jp