  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:shinjuku-golden-gai', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Shinjuku Golden Gai', 'nightlife', 'A historic nightlife area consisting of six narrow alleys lined with over 200 tiny bars, each with its own unique theme and intimate seating.', '[{"text": "Look out for signs showing whether a bar charges a cover fee (typically 500 to 1,000 Yen) or welcomes English speakers.", "source_url": "https://en.wikipedia.org/wiki/Shinjuku_Golden_Gai"}]'::jsonb, 'unknown', 'unknown', 'Shinjuku-sanchome Station', null, 35.6939, 139.705, '1-1-6 Kabukicho, Shinjuku-ku, Tokyo 160-0021', null, null, null, '{}', '{"http://goldengai.jp/","https://en.wikipedia.org/wiki/Shinjuku_Golden_Gai"}', '{"name": "https://en.wikipedia.org/wiki/Shinjuku_Golden_Gai", "description": "https://en.wikipedia.org/wiki/Shinjuku_Golden_Gai", "station": "https://en.wikipedia.org/wiki/Shinjuku_Golden_Gai", "lat": "https://en.wikipedia.org/wiki/Shinjuku_Golden_Gai", "lng": "https://en.wikipedia.org/wiki/Shinjuku_Golden_Gai", "address": "https://en.wikipedia.org/wiki/Shinjuku_Golden_Gai"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/d/da/Golden_Gai_%283741285627%29.jpg", "credit": "urbzoo", "license": "CC BY 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Golden_Gai_%283741285627%29.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/d/df/Golden_Gai_%283741297195%29.jpg", "credit": "urbzoo", "license": "CC BY 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Golden_Gai_%283741297195%29.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:hanazono-shrine', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Hanazono Shrine', 'shrine', 'A tranquil and historic Shinto shrine located near Kabukicho, acting as a peaceful retreat from the surrounding city''s bustling neon-lit streets.', '[{"text": "Visit on Sundays to browse the antique flea market held on the shrine grounds.", "source_url": "https://en.wikipedia.org/wiki/Hanazono_Shrine"}]'::jsonb, 'Open 24 hours', 'known', 'Shinjuku-sanchome Station', null, 35.693553, 139.705184, '5-17-3 Shinjuku, Shinjuku-ku, Tokyo 160-0022', null, null, null, '{}', '{"http://www.hanazono-jinja.or.jp/","https://en.wikipedia.org/wiki/Hanazono_Shrine"}', '{"name": "https://en.wikipedia.org/wiki/Hanazono_Shrine", "description": "https://en.wikipedia.org/wiki/Hanazono_Shrine", "hours": "https://en.wikipedia.org/wiki/Hanazono_Shrine", "station": "https://en.wikipedia.org/wiki/Hanazono_Shrine", "lat": "https://en.wikipedia.org/wiki/Hanazono_Shrine", "lng": "https://en.wikipedia.org/wiki/Hanazono_Shrine", "address": "https://en.wikipedia.org/wiki/Hanazono_Shrine"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/a/a9/Hanazono_Shrine_%283%29.jpg", "credit": "Fay1982", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Hanazono_Shrine_%283%29.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/0/07/Hanazono_Shrine_Detail.jpg", "credit": "Dmitri Popov", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Hanazono_Shrine_Detail.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:isetan-shinjuku', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Isetan Shinjuku', 'shopping-street', 'A legendary and elegant department store in Shinjuku, widely celebrated for its fashion floors and magnificent basement food hall (depachika).', '[{"text": "Head straight to the basement (B1) level to browse one of Tokyo''s finest selections of high-end desserts, pastries, and traditional bento boxes.", "source_url": "https://en.wikipedia.org/wiki/Isetan"}]'::jsonb, '10:00 AM - 8:00 PM', 'known', 'Shinjuku-sanchome Station', null, 35.69156, 139.704651, '3-14-1 Shinjuku, Shinjuku-ku, Tokyo 160-0022', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Isetan","https://www.mistore.jp/store/shinjuku/foreign_customer/en.html"}', '{"name": "https://en.wikipedia.org/wiki/Isetan", "description": "https://en.wikipedia.org/wiki/Isetan", "hours": "https://en.wikipedia.org/wiki/Isetan", "station": "https://en.wikipedia.org/wiki/Isetan", "lat": "https://en.wikipedia.org/wiki/Isetan", "lng": "https://en.wikipedia.org/wiki/Isetan", "address": "https://en.wikipedia.org/wiki/Isetan"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/2/23/Km_Kanko_Bus_5902_Isetan_Shuttle_Coach_Rosa_BE740.jpg", "credit": "Comyu", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Km_Kanko_Bus_5902_Isetan_Shuttle_Coach_Rosa_BE740.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:lumine-shinjuku', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Lumine Shinjuku', 'shopping-street', 'A popular modern shopping mall complex directly integrated with Shinjuku Station, offering multiple floors of stylish clothing, cosmetics, and cafes.', '[{"text": "Lumine Shinjuku is split into Lumine 1 and Lumine 2; Lumine 2 is located right above the South Exit of Shinjuku Station.", "source_url": "https://www.lumine.ne.jp/shinjuku/"}]'::jsonb, '11:00 AM - 9:00 PM', 'known', 'Shinjuku Station', null, 35.689222, 139.699365, '3-38-2 Shinjuku, Shinjuku-ku, Tokyo 160-0022', null, null, null, '{}', '{"https://www.lumine.ne.jp/shinjuku/"}', '{"name": "https://www.lumine.ne.jp/shinjuku/", "description": "https://www.lumine.ne.jp/shinjuku/", "hours": "https://www.lumine.ne.jp/shinjuku/", "station": "https://www.lumine.ne.jp/shinjuku/", "lat": "https://www.lumine.ne.jp/shinjuku/", "lng": "https://www.lumine.ne.jp/shinjuku/", "address": "https://www.lumine.ne.jp/shinjuku/"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/5/52/Entree_sud_gare_de_shinjuku.JPG", "credit": "Lydie Guézengar", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Entree_sud_gare_de_shinjuku.JPG", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:newoman-shinjuku', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'NEWoMan Shinjuku', 'shopping-street', 'A sleek, upscale lifestyle shopping mall tailored for professional women, featuring curated boutiques, bakeries, and high-end restaurants near Shinjuku Station.', '[{"text": "Visit the 2nd-floor food hall which offers high-quality international dining options and artisanal coffee with late-night hours.", "source_url": "https://www.newoman.jp/shinjuku/"}]'::jsonb, '11:00 AM - 8:30 PM', 'known', 'Shinjuku Station', null, 35.688825, 139.701389, '4-1-6 Shinjuku, Shinjuku-ku, Tokyo 160-0022', null, null, null, '{}', '{"https://www.newoman.jp/shinjuku/"}', '{"name": "https://www.newoman.jp/shinjuku/", "description": "https://www.newoman.jp/shinjuku/", "hours": "https://www.newoman.jp/shinjuku/", "station": "https://www.newoman.jp/shinjuku/", "lat": "https://www.newoman.jp/shinjuku/", "lng": "https://www.newoman.jp/shinjuku/", "address": "https://www.newoman.jp/shinjuku/"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/6/66/NEWoMan_Shinjuku_Food_Hall_2018.jpg", "credit": "Wpcpey", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:NEWoMan_Shinjuku_Food_Hall_2018.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/e/ec/NEWoMan_Shinjuku_outside_view_2018.jpg", "credit": "Wpcpey", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:NEWoMan_Shinjuku_outside_view_2018.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:shinjuku-central-park', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Shinjuku Central Park', 'park', 'A spacious public park located in Nishi-Shinjuku amidst towering skyscrapers, offering green lawns, a multi-tier fountain, and quiet walking paths.', '[{"text": "The park often hosts weekend flea markets and food festivals which are popular with locals and visitors.", "source_url": "https://en.wikipedia.org/wiki/Shinjuku_Central_Park"}]'::jsonb, 'Open 24 hours', 'known', 'Tocho-mae Station', null, 35.69007, 139.68947, '2-11 Nishi-Shinjuku, Shinjuku-ku, Tokyo 160-0023', null, null, null, '{}', '{"https://parks.prfj.or.jp/shinjuku/","https://en.wikipedia.org/wiki/Shinjuku_Central_Park"}', '{"name": "https://en.wikipedia.org/wiki/Shinjuku_Central_Park", "description": "https://en.wikipedia.org/wiki/Shinjuku_Central_Park", "hours": "https://parks.prfj.or.jp/shinjuku/", "station": "https://en.wikipedia.org/wiki/Shinjuku_Central_Park", "lat": "https://en.wikipedia.org/wiki/Shinjuku_Central_Park", "lng": "https://en.wikipedia.org/wiki/Shinjuku_Central_Park", "address": "https://parks.prfj.or.jp/shinjuku/"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/6/64/Pathway_in_Shinjuku_Central_Park_in_Tokyo%2C_2019_-_077.jpg", "credit": "Another Believer", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Pathway_in_Shinjuku_Central_Park_in_Tokyo,_2019_-_077.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/5/54/Rain_%40_Shinjuku_Central_Park_%40_Nishi-Shinjuku_%2811450005445%29.jpg", "credit": "Guilhem Vellut from Annecy, France", "license": "CC BY 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Rain_@_Shinjuku_Central_Park_@_Nishi-Shinjuku_(11450005445).jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:mode-gakuen-cocoon-tower', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Mode Gakuen Cocoon Tower', 'attraction', 'An architecturally stunning, cocoon-shaped educational skyscraper that houses three vocational colleges and dominates the Nishi-Shinjuku skyline.', '[{"text": "The tower''s distinctive crisscross pattern resembles a cocoon, symbolizing the nurturing of students inside.", "source_url": "https://en.wikipedia.org/wiki/Mode_Gakuen_Cocoon_Tower"}]'::jsonb, 'unknown', 'unknown', 'Shinjuku Station', null, 35.691667, 139.696944, '1-7-3 Nishi-Shinjuku, Shinjuku-ku, Tokyo 160-0023', null, null, null, '{}', '{"https://www.mode.ac.jp/tokyo","https://en.wikipedia.org/wiki/Mode_Gakuen_Cocoon_Tower"}', '{"name": "https://en.wikipedia.org/wiki/Mode_Gakuen_Cocoon_Tower", "description": "https://en.wikipedia.org/wiki/Mode_Gakuen_Cocoon_Tower", "station": "https://en.wikipedia.org/wiki/Mode_Gakuen_Cocoon_Tower", "lat": "https://en.wikipedia.org/wiki/Mode_Gakuen_Cocoon_Tower", "lng": "https://en.wikipedia.org/wiki/Mode_Gakuen_Cocoon_Tower", "address": "https://en.wikipedia.org/wiki/Mode_Gakuen_Cocoon_Tower"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/7/7b/2018_Mode_Gakuen_Cocoon_Tower_2.jpg", "credit": "Kakidai", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:2018_Mode_Gakuen_Cocoon_Tower_2.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/6/68/2019_Mode_Gakuen_Cocoon_Tower.jpg", "credit": "Kakidai", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:2019_Mode_Gakuen_Cocoon_Tower.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:shinjuku-ni-chome', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Shinjuku Ni-chome', 'nightlife', 'Tokyo''s famous, vibrant LGBTQ+ district, home to the world''s highest concentration of gay and lesbian bars nestled in cozy blocks.', '[{"text": "Most bars here are very small, seating under 10 people. Some bars cater exclusively to regular customers or specific groups, so look for welcoming signs or English menus.", "source_url": "https://en.wikipedia.org/wiki/Shinjuku_Ni-ch%C5%8Dme"}]'::jsonb, 'unknown', 'unknown', 'Shinjuku-sanchome Station', null, 35.69, 139.706667, '2 Shinjuku, Shinjuku-ku, Tokyo 160-0022', null, null, null, '{}', '{"https://www.gotokyo.org/en/destinations/western-tokyo/shinjuku/index.html","https://en.wikipedia.org/wiki/Shinjuku_Ni-ch%C5%8Dme"}', '{"name": "https://en.wikipedia.org/wiki/Shinjuku_Ni-ch%C5%8Dme", "description": "https://en.wikipedia.org/wiki/Shinjuku_Ni-ch%C5%8Dme", "station": "https://en.wikipedia.org/wiki/Shinjuku_Ni-ch%C5%8Dme", "lat": "https://en.wikipedia.org/wiki/Shinjuku_Ni-ch%C5%8Dme", "lng": "https://en.wikipedia.org/wiki/Shinjuku_Ni-ch%C5%8Dme", "address": "https://en.wikipedia.org/wiki/Shinjuku_Ni-ch%C5%8Dme"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/d/dc/Shinjuku_Ni-ch%C5%8Dme.jpg", "credit": "LittleT889", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Shinjuku_Ni-ch%C5%8Dme.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/f/fb/Shinjuku_2-chome_2013-01-30.JPG", "credit": "Asanagi", "license": "CC0", "source_url": "https://commons.wikimedia.org/wiki/File:Shinjuku_2-chome_2013-01-30.JPG", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:godzilla-head', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Godzilla Head', 'attraction', 'A life-sized, iconic replica of the legendary monster''s head, peering over the rooftop of the Toho Building in Kabukicho.', '[{"text": "The Godzilla head roars, blows mist, and lights up on the hour from 12:00 PM to 8:00 PM.", "source_url": "https://en.wikipedia.org/wiki/Godzilla_head"}]'::jsonb, 'Open 24 hours', 'known', 'Shinjuku Station', null, 35.695034, 139.701909, '1-19-1 Kabukicho, Shinjuku-ku, Tokyo 160-0021', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Godzilla_head"}', '{"name": "https://en.wikipedia.org/wiki/Godzilla_head", "description": "https://en.wikipedia.org/wiki/Godzilla_head", "hours": "https://en.wikipedia.org/wiki/Godzilla_head", "station": "https://en.wikipedia.org/wiki/Godzilla_head", "lat": "https://en.wikipedia.org/wiki/Godzilla_head", "lng": "https://en.wikipedia.org/wiki/Godzilla_head", "address": "https://en.wikipedia.org/wiki/Godzilla_head"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/2/23/Shinjuku_%2824850285822%29.jpg", "credit": "Laika ac from UK", "license": "CC BY-SA 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Shinjuku_%2824850285822%29.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:taisoji-temple', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Taisoji Temple', 'temple', 'A quiet Buddhist temple in Shinjuku that dates back to the Edo period, containing a giant red bronze statue of Jizo Bosatsu and a famous Enma statue.', '[{"text": "Step inside to see the massive 2.6-meter bronze Jizo Bosatsu, which is one of the six great Jizo statues of Edo.", "source_url": "https://ja.wikipedia.org/wiki/%E5%A4%AA%E5%AE%97%E5%AF%BA"}]'::jsonb, '9:00 AM - 5:00 PM', 'known', 'Shinjuku-gyoemmae Station', null, 35.689861, 139.709361, '2-9-2 Shinjuku, Shinjuku-ku, Tokyo 160-0022', null, null, null, '{}', '{"https://ja.wikipedia.org/wiki/%E5%A4%AA%E5%AE%97%E5%AF%BA"}', '{"name": "https://ja.wikipedia.org/wiki/%E5%A4%AA%E5%AE%97%E5%AF%BA", "description": "https://ja.wikipedia.org/wiki/%E5%A4%AA%E5%AE%97%E5%AF%BA", "hours": "https://ja.wikipedia.org/wiki/%E5%A4%AA%E5%AE%97%E5%AF%BA", "station": "https://ja.wikipedia.org/wiki/%E5%A4%AA%E5%AE%97%E5%AF%BA", "lat": "https://ja.wikipedia.org/wiki/%E5%A4%AA%E5%AE%97%E5%AF%BA", "lng": "https://ja.wikipedia.org/wiki/%E5%A4%AA%E5%AE%97%E5%AF%BA", "address": "https://ja.wikipedia.org/wiki/%E5%A4%AA%E5%AE%97%E5%AF%BA"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/c/c5/Taiso-ji_%28Shinjuku%29.jpg", "credit": "Suikotei", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Taiso-ji_%28Shinjuku%29.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/b/ba/Buddhist_cemetery%2C_Taiso-ji_%283813422412%29.jpg", "credit": "Andrea Schaffer from Sydney, Australia", "license": "CC BY 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Buddhist_cemetery%2C_Taiso-ji_%283813422412%29.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:sompo-museum-of-art', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Sompo Museum of Art', 'museum', 'An art museum in Nishi-Shinjuku dedicated to modern paintings, famous for housing Vincent van Gogh''s iconic ''Sunflowers'' and works by Seiji Togo.', '[{"text": "Advance reservations online are highly recommended to ensure entry on popular exhibition days.", "source_url": "https://www.sompo-museum.org/en/"}]'::jsonb, '10:00 AM - 6:00 PM', 'known', 'Shinjuku Station', null, 35.69277778, 139.69611111, '1-26-1 Nishi-Shinjuku, Shinjuku-ku, Tokyo 160-8338', null, null, null, '{}', '{"https://www.sompo-museum.org/en/","https://en.wikipedia.org/wiki/Sompo_Museum_of_Art"}', '{"name": "https://en.wikipedia.org/wiki/Sompo_Museum_of_Art", "description": "https://en.wikipedia.org/wiki/Sompo_Museum_of_Art", "hours": "https://www.sompo-museum.org/en/", "station": "https://www.sompo-museum.org/en/", "lat": "https://en.wikipedia.org/wiki/Sompo_Museum_of_Art", "lng": "https://en.wikipedia.org/wiki/Sompo_Museum_of_Art", "address": "https://www.sompo-museum.org/en/"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/4/4e/Sompo_museum_202002.jpg", "credit": "鋰香具師", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Sompo_museum_202002.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/1/1d/Sompo_japan_museum_of_arts_shinjuku.jpg", "credit": "Tengusabaki", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Sompo_japan_museum_of_arts_shinjuku.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:toyama-park', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Toyama Park', 'park', 'A large metropolitan park in Shinjuku, famous for containing Hakone Yama, the highest natural hilltop point on the Yamanote line ring.', '[{"text": "Climb to the top of Hakone Yama, which is 44.6 meters above sea level, and request a summit certificate from the park service office.", "source_url": "https://ja.wikipedia.org/wiki/%E6%88%B8%E5%B1%B1%E5%85%AC%E5%9C%92"}]'::jsonb, 'Open 24 hours', 'known', 'Nishi-waseda Station', null, 35.705333, 139.704556, '1-chome to 3-chome Toyama, Shinjuku-ku, Tokyo 162-0052', null, null, null, '{}', '{"https://ja.wikipedia.org/wiki/%E6%88%B8%E5%B1%B1%E5%85%AC%E5%9C%92"}', '{"name": "https://ja.wikipedia.org/wiki/%E6%88%B8%E5%B1%B1%E5%85%AC%E5%9C%92", "description": "https://ja.wikipedia.org/wiki/%E6%88%B8%E5%B1%B1%E5%85%AC%E5%9C%92", "hours": "https://ja.wikipedia.org/wiki/%E6%88%B8%E5%B1%B1%E5%85%AC%E5%9C%92", "station": "https://ja.wikipedia.org/wiki/%E6%88%B8%E5%B1%B1%E5%85%AC%E5%9C%92", "lat": "https://ja.wikipedia.org/wiki/%E6%88%B8%E5%B1%B1%E5%85%AC%E5%9C%92", "lng": "https://ja.wikipedia.org/wiki/%E6%88%B8%E5%B1%B1%E5%85%AC%E5%9C%92", "address": "https://ja.wikipedia.org/wiki/%E6%88%B8%E5%B1%B1%E5%85%AC%E5%9C%92"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/e/ec/Cat_%40_Toyama_Park_%40_Shinjuku_%2815213175236%29.jpg", "credit": "Guilhem Vellut from Annecy, France", "license": "CC BY 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Cat_%40_Toyama_Park_%40_Shinjuku_%2815213175236%29.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:yayoi-kusama-museum', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Yayoi Kusama Museum', 'museum', 'A private museum in Shinjuku dedicated to the avant-garde artwork of Yayoi Kusama, featuring her iconic polka dots and immersive infinity rooms.', '[{"text": "Tickets must be purchased online in advance and are sold for specific, timed entry slots.", "source_url": "https://yayoikusamamuseum.jp/en/home/"}]'::jsonb, '11:00 AM - 5:30 PM', 'known', 'Ushigome-yanagicho Station', null, 35.7032, 139.72648, '107 Bentencho, Shinjuku-ku, Tokyo 162-0851', null, null, null, '{}', '{"https://yayoikusamamuseum.jp/en/home/","https://en.wikipedia.org/wiki/Yayoi_Kusama_Museum"}', '{"name": "https://en.wikipedia.org/wiki/Yayoi_Kusama_Museum", "description": "https://en.wikipedia.org/wiki/Yayoi_Kusama_Museum", "hours": "https://yayoikusamamuseum.jp/en/home/", "station": "https://yayoikusamamuseum.jp/en/home/", "lat": "https://en.wikipedia.org/wiki/Yayoi_Kusama_Museum", "lng": "https://en.wikipedia.org/wiki/Yayoi_Kusama_Museum", "address": "https://yayoikusamamuseum.jp/en/home/"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/c/cc/YAYOI_KUSAMA_MUSEUM_%E8%8D%89%E9%96%93%E5%BD%80%E5%BC%A5%E7%BE%8E%E8%A1%93%E9%A4%A82018frontCIMG3591.jpg", "credit": "Bject", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:YAYOI_KUSAMA_MUSEUM_%E8%8D%89%E9%96%93%E5%BD%80%E5%BC%A5%E7%BE%8E%E8%A1%93%E9%A4%A82018frontCIMG3591.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/c/cd/YAYOI_KUSAMA_MUSEUM_%E8%8D%89%E9%96%93%E5%BD%80%E5%BC%A5%E7%BE%8E%E8%A1%93%E9%A4%A82018sideCIMG3596.jpg", "credit": "Bject", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:YAYOI_KUSAMA_MUSEUM_%E8%8D%89%E9%96%93%E5%BD%80%E5%BC%A5%E7%BE%8E%E8%A1%93%E9%A4%A82018sideCIMG3596.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:thermae-yu', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Thermae-Yu', 'bath', 'A huge, luxury six-story hot spring bathhouse in Kabukicho, featuring real onsen mineral water trucked in daily from Izu.', '[{"text": "Be aware that guests with visible tattoos are strictly not permitted to enter the facility.", "source_url": "https://thermae-yu.jp/"}]'::jsonb, 'Open 24 hours', 'known', 'Shinjuku-sanchome Station', null, 35.694662, 139.704987, '1-1-2 Kabukicho, Shinjuku-ku, Tokyo 160-0021', null, null, null, '{}', '{"https://thermae-yu.jp/"}', '{"name": "https://thermae-yu.jp/", "description": "https://thermae-yu.jp/", "hours": "https://thermae-yu.jp/", "station": "https://thermae-yu.jp/", "lat": "https://thermae-yu.jp/", "lng": "https://thermae-yu.jp/", "address": "https://thermae-yu.jp/"}'::jsonb, null, '[]'::jsonb, 'gemini-3.5-flash', 'approved', '["no verifiable image"]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:shinjuku:kagurazaka', 'Kanto', 'Tokyo', 'Shinjuku', 'JP', 'Kagurazaka', 'scenic-walk', 'A charming, historic neighborhood in Shinjuku featuring stone-paved alleys, quiet cafes, and a unique blend of traditional geisha culture and French dining.', '[{"text": "Wander off the main street into the narrow, winding cobblestone alleyways like Hyogo-cho or Kakurenbo-yokocho to discover hidden tea houses and high-end restaurants.", "source_url": "https://en.wikipedia.org/wiki/Kagurazaka"}]'::jsonb, 'Open 24 hours', 'known', 'Kagurazaka Station', null, 35.70246111111111, 139.739, 'Kagurazaka, Shinjuku-ku, Tokyo 162-0825', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Kagurazaka"}', '{"name": "https://en.wikipedia.org/wiki/Kagurazaka", "description": "https://en.wikipedia.org/wiki/Kagurazaka", "hours": "https://en.wikipedia.org/wiki/Kagurazaka", "station": "https://en.wikipedia.org/wiki/Kagurazaka", "lat": "https://en.wikipedia.org/wiki/Kagurazaka", "lng": "https://en.wikipedia.org/wiki/Kagurazaka", "address": "https://en.wikipedia.org/wiki/Kagurazaka"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/7/75/6_Chome_Kagurazaka%2C_Shinjuku-ku%2C_T%C5%8Dky%C5%8D-to_162-0825%2C_Japan_-_panoramio.jpg", "credit": "Nagono", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:6_Chome_Kagurazaka%2C_Shinjuku-ku%2C_T%C5%8Dky%C5%8D-to_162-0825%2C_Japan_-_panoramio.jpg", "is_exact_place": true, "provider": "wikimedia"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/3/30/Baika-tei_in_Kagurazaka_2022-12-17_%281%29_as.jpg", "credit": "Araisyohei", "license": "CC BY 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Baika-tei_in_Kagurazaka_2022-12-17_%281%29_as.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:sens-ji', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Sensō-ji', 'temple', 'Tokyo''s oldest and most iconic Buddhist temple, dedicated to the Bodhisattva Kannon and featuring a grand main hall and five-story pagoda.', '[{"text": "Visit early in the morning or late at night when the main hall is closed but the temple grounds are beautifully illuminated and peaceful.", "source_url": "https://www.senso-ji.jp/"}]'::jsonb, '6:00 AM - 5:00 PM (October to March: 6:30 AM - 5:00 PM)', 'known', 'Asakusa Station', null, 35.714556, 139.796639, '2-3-1 Asakusa, Taito City, Tokyo', null, null, null, '{}', '{"https://www.senso-ji.jp/","https://en.wikipedia.org/wiki/Sens%C5%8D-ji"}', '{"name": "https://en.wikipedia.org/wiki/Sens%C5%8D-ji", "description": "https://en.wikipedia.org/wiki/Sens%C5%8D-ji", "hours": "https://www.senso-ji.jp/english/", "station": "https://www.senso-ji.jp/english/", "lat": "https://en.wikipedia.org/wiki/Sens%C5%8D-ji", "lng": "https://en.wikipedia.org/wiki/Sens%C5%8D-ji", "address": "https://en.wikipedia.org/wiki/Sens%C5%8D-ji"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/4/43/Sensoji_2023.jpg", "credit": "Akonnchiroll", "license": "CC0", "source_url": "https://commons.wikimedia.org/wiki/File:Sensoji_2023.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:kaminarimon', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Kaminarimon', 'attraction', 'The iconic outer entrance gate to Sensō-ji Temple, famous for its massive red paper lantern, thunder god statues, and lively atmosphere.', '[{"text": "Look underneath the giant paper lantern to see the beautiful, intricate dragon carving on its wooden base.", "source_url": "https://www.senso-ji.jp/guide/guide01.html"}]'::jsonb, 'Open 24 hours', 'known', 'Asakusa Station', null, 35.711133, 139.796325, '1-2-1 Asakusa, Taito City, Tokyo', null, null, null, '{}', '{"https://www.senso-ji.jp/guide/guide01.html","https://en.wikipedia.org/wiki/Kaminarimon"}', '{"name": "https://en.wikipedia.org/wiki/Kaminarimon", "description": "https://en.wikipedia.org/wiki/Kaminarimon", "hours": "https://www.senso-ji.jp/guide/guide01.html", "station": "https://www.senso-ji.jp/guide/guide01.html", "lat": "https://en.wikipedia.org/wiki/Kaminarimon", "lng": "https://en.wikipedia.org/wiki/Kaminarimon", "address": "https://www.senso-ji.jp/guide/guide01.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/8/81/Day2-2_%2840909714314%29.jpg", "credit": "Ajay Suresh", "license": "CC BY 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Day2-2_(40909714314).jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:nakamise-shopping-street', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Nakamise Shopping Street', 'shopping-street', 'A historic, bustling approach to Sensō-ji Temple lined with dozens of small stalls selling traditional snacks, souvenirs, and crafts.', '[{"text": "Do not eat while walking down the street; it is customary to consume purchased snacks directly in front of the shop where they were bought.", "source_url": "https://www.asakusa-nakamise.jp/"}]'::jsonb, '9:00 AM - 7:00 PM (varies by shop)', 'known', 'Asakusa Station', null, 35.7128, 139.7965, '2-3-1 Asakusa, Taito City, Tokyo', null, null, null, '{}', '{"https://www.asakusa-nakamise.jp/","https://en.wikipedia.org/wiki/Sens%C5%8D-ji"}', '{"name": "https://www.asakusa-nakamise.jp/", "description": "https://www.asakusa-nakamise.jp/", "hours": "https://www.asakusa-nakamise.jp/", "station": "https://www.asakusa-nakamise.jp/", "lat": "https://en.wikipedia.org/wiki/Sens%C5%8D-ji", "lng": "https://en.wikipedia.org/wiki/Sens%C5%8D-ji", "address": "https://www.asakusa-nakamise.jp/"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/4/41/Asakusa_sensoji07s3200.jpg", "credit": "663highland", "license": "CC BY 2.5", "source_url": "https://commons.wikimedia.org/wiki/File:Asakusa_sensoji07s3200.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:asakusa-shrine', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Asakusa Shrine', 'shrine', 'A peaceful Shinto shrine adjacent to Sensō-ji, built to honor the three men who founded the temple and celebrated for hosting the massive Sanja Matsuri festival.', '[{"text": "Look for the stone monument of two guardians on the shrine grounds, dedicated to the shrine founders.", "source_url": "https://www.asakusajinja.jp/"}]'::jsonb, 'Open 24 hours (Shrine office: 9:00 AM - 4:30 PM)', 'known', 'Asakusa Station', null, 35.715139, 139.797436, '2-3-1 Asakusa, Taito City, Tokyo', null, null, null, '{}', '{"https://www.asakusajinja.jp/","https://en.wikipedia.org/wiki/Asakusa_Shrine"}', '{"name": "https://en.wikipedia.org/wiki/Asakusa_Shrine", "description": "https://en.wikipedia.org/wiki/Asakusa_Shrine", "hours": "https://www.asakusajinja.jp/english/", "station": "https://www.asakusajinja.jp/english/", "lat": "https://en.wikipedia.org/wiki/Asakusa_Shrine", "lng": "https://en.wikipedia.org/wiki/Asakusa_Shrine", "address": "https://en.wikipedia.org/wiki/Asakusa_Shrine"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/c/c1/Asakusa_shrine_2012.JPG", "credit": "Kakidai", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Asakusa_shrine_2012.JPG", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:ueno-park', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Ueno Park', 'park', 'A vast public park in Ueno housing multiple museums, shrines, Shinobazu Pond, and thousands of cherry trees that draw massive crowds in spring.', '[{"text": "Stop by the bronze statue of Saigo Takamori, a key historical figure of the Meiji Restoration, near the park''s southern entrance.", "source_url": "https://www.tokyo-park.or.jp/park/format/index038.html"}]'::jsonb, '5:00 AM - 11:00 PM', 'known', 'Ueno Station', null, 35.712222, 139.771111, 'Uenokoen, Taito City, Tokyo', null, null, null, '{}', '{"https://www.tokyo-park.or.jp/park/format/index038.html","https://en.wikipedia.org/wiki/Ueno_Park"}', '{"name": "https://en.wikipedia.org/wiki/Ueno_Park", "description": "https://en.wikipedia.org/wiki/Ueno_Park", "hours": "https://www.tokyo-park.or.jp/park/format/index038.html", "station": "https://www.tokyo-park.or.jp/park/format/index038.html", "lat": "https://en.wikipedia.org/wiki/Ueno_Park", "lng": "https://en.wikipedia.org/wiki/Ueno_Park", "address": "https://en.wikipedia.org/wiki/Ueno_Park"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/1/18/Ueno_park.jpg", "credit": "Bernard Gagnon", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Ueno_park.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:ueno-zoo', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Ueno Zoo', 'attraction', 'Japan''s oldest zoo, established in 1882, home to hundreds of species including giant pandas and a five-story pagoda within its scenic grounds.', '[{"text": "Purchase tickets online in advance to skip the long ticket queues at the main gate, especially during weekends and public holidays.", "source_url": "https://www.tokyo-zoo.net/zoo/ueno/"}]'::jsonb, '9:30 AM - 5:00 PM (Closed Mondays and Dec 29-Jan 1)', 'known', 'Ueno Station', null, 35.7175, 139.771389, '9-83 Uenokoen, Taito City, Tokyo', null, null, null, '{}', '{"https://www.tokyo-zoo.net/zoo/ueno/","https://en.wikipedia.org/wiki/Ueno_Zoo"}', '{"name": "https://en.wikipedia.org/wiki/Ueno_Zoo", "description": "https://en.wikipedia.org/wiki/Ueno_Zoo", "hours": "https://www.tokyo-zoo.net/zoo/ueno/", "station": "https://www.tokyo-zoo.net/zoo/ueno/", "lat": "https://en.wikipedia.org/wiki/Ueno_Zoo", "lng": "https://en.wikipedia.org/wiki/Ueno_Zoo", "address": "https://www.tokyo-zoo.net/zoo/ueno/"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Ueno_Zoo_2012.JPG", "credit": "Kakidai", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Ueno_Zoo_2012.JPG", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:tokyo-national-museum', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Tokyo National Museum', 'museum', 'The oldest and largest national museum in Japan, displaying an extensive collection of ancient Japanese art, national treasures, and archaeological finds.', '[{"text": "Visit the Kuromon (Black Gate), an Edo-period gate of a feudal lord''s mansion, located in the museum''s outdoor area.", "source_url": "https://www.tnm.jp/"}]'::jsonb, '9:30 AM - 5:00 PM (Closed Mondays)', 'known', 'Ueno Station', null, 35.718889, 139.776389, '13-9 Uenokoen, Taito City, Tokyo', null, null, null, '{}', '{"https://www.tnm.jp/","https://en.wikipedia.org/wiki/Tokyo_National_Museum"}', '{"name": "https://en.wikipedia.org/wiki/Tokyo_National_Museum", "description": "https://en.wikipedia.org/wiki/Tokyo_National_Museum", "hours": "https://www.tnm.jp/modules/r_free_page/index.php?id=113", "station": "https://www.tnm.jp/modules/r_free_page/index.php?id=114", "lat": "https://en.wikipedia.org/wiki/Tokyo_National_Museum", "lng": "https://en.wikipedia.org/wiki/Tokyo_National_Museum", "address": "https://www.tnm.jp/modules/r_free_page/index.php?id=114"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/a/a5/Tokyo_National_Museum%2C_Honkan_2010.jpg", "credit": "Wiiii", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Tokyo_National_Museum,_Honkan_2010.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:national-museum-of-nature-and-science', 'Kanto', 'Tokyo', 'Taito', 'JP', 'National Museum of Nature and Science', 'museum', 'A world-class science museum boasting extensive collections of fossils, dinosaur skeletons, and interactive exhibits detailing natural history and scientific advancements.', '[{"text": "Don''t miss the Theatre 360, a 3D spherical theater that provides a unique, immersive visual experience of evolution and the earth.", "source_url": "https://www.kahaku.go.jp/"}]'::jsonb, '9:00 AM - 5:00 PM (Closed Mondays)', 'known', 'Ueno Station', null, 35.716319, 139.776544, '7-20 Uenokoen, Taito City, Tokyo', null, null, null, '{}', '{"https://www.kahaku.go.jp/","https://en.wikipedia.org/wiki/National_Museum_of_Nature_and_Science"}', '{"name": "https://en.wikipedia.org/wiki/National_Museum_of_Nature_and_Science", "description": "https://en.wikipedia.org/wiki/National_Museum_of_Nature_and_Science", "hours": "https://www.kahaku.go.jp/english/user-guide/access/", "station": "https://www.kahaku.go.jp/english/user-guide/access/", "lat": "https://en.wikipedia.org/wiki/National_Museum_of_Nature_and_Science", "lng": "https://en.wikipedia.org/wiki/National_Museum_of_Nature_and_Science", "address": "https://www.kahaku.go.jp/english/user-guide/access/"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/3/3d/NMNC01s3200.jpg", "credit": "663highland", "license": "CC BY 2.5", "source_url": "https://commons.wikimedia.org/wiki/File:NMNC01s3200.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:national-museum-of-western-art', 'Kanto', 'Tokyo', 'Taito', 'JP', 'National Museum of Western Art', 'museum', 'Japan''s premier museum for Western art, displaying European paintings and Rodin sculptures in a landmark building designed by French architect Le Corbusier.', '[{"text": "Admire the bronze casts of Auguste Rodin''s masterpiece sculptures, including ''The Gates of Hell'' and ''The Thinker'', displayed in the front courtyard.", "source_url": "https://www.nmwa.go.jp/"}]'::jsonb, '9:30 AM - 5:30 PM (Fridays and Saturdays: 9:30 AM - 8:00 PM) (Closed Mondays)', 'known', 'Ueno Station', null, 35.715357, 139.77585, '7-7 Uenokoen, Taito City, Tokyo', null, null, null, '{}', '{"https://www.nmwa.go.jp/","https://en.wikipedia.org/wiki/National_Museum_of_Western_Art"}', '{"name": "https://en.wikipedia.org/wiki/National_Museum_of_Western_Art", "description": "https://en.wikipedia.org/wiki/National_Museum_of_Western_Art", "hours": "https://www.nmwa.go.jp/en/visiting/hours.html", "station": "https://www.nmwa.go.jp/en/visiting/index.html", "lat": "https://en.wikipedia.org/wiki/National_Museum_of_Western_Art", "lng": "https://en.wikipedia.org/wiki/National_Museum_of_Western_Art", "address": "https://www.nmwa.go.jp/en/visiting/index.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/9/9d/National_museum_of_western_art05s3200.jpg", "credit": "663highland", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:National_museum_of_western_art05s3200.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:ameya-yokoch', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Ameya-Yokochō', 'market', 'A vibrant, open-air market street running along the railway tracks, packed with shops selling street food, spices, cheap clothing, and fresh seafood.', '[{"text": "Bargain respectfully at the fish and food stalls, which is a rare shopping custom in Tokyo, and enjoy cheap skewers or fresh fruit slices.", "source_url": "https://www.ameyoko.net/"}]'::jsonb, '10:00 AM - 8:00 PM (varies by shop)', 'known', 'Ueno Station', null, 35.710059, 139.774543, '4-9-15 Ueno, Taito City, Tokyo', null, null, null, '{}', '{"https://www.ameyoko.net/","https://en.wikipedia.org/wiki/Ameya-Yokoch%C5%8D"}', '{"name": "https://en.wikipedia.org/wiki/Ameya-Yokoch%C5%8D", "description": "https://en.wikipedia.org/wiki/Ameya-Yokoch%C5%8D", "hours": "https://www.ameyoko.net/", "station": "https://www.ameyoko.net/", "lat": "https://en.wikipedia.org/wiki/Ameya-Yokoch%C5%8D", "lng": "https://en.wikipedia.org/wiki/Ameya-Yokoch%C5%8D", "address": "https://www.ameyoko.net/"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/5/5e/Ueno_20241210_133139.jpg", "credit": "Ka23 13", "license": "CC BY 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Ueno_20241210_133139.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:kappabashi-dori', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Kappabashi-dori', 'shopping-street', 'Tokyo''s famous restaurant supply street, lined with over 150 shops specializing in kitchenware, tableware, knives, and incredibly realistic plastic food replicas.', '[{"text": "Shop for high-quality Japanese chef knives or pick up incredibly realistic plastic food models (sampuru) as a unique, hand-crafted Tokyo souvenir.", "source_url": "https://www.kappabashi.or.jp/"}]'::jsonb, '9:00 AM - 5:00 PM (Many shops closed Sundays)', 'known', 'Tawaramachi Station', null, 35.71675, 139.78915, '3-18-2 Matsugaya, Taito City, Tokyo', null, null, null, '{}', '{"https://www.kappabashi.or.jp/","https://en.wikipedia.org/wiki/Kappabashi-dori"}', '{"name": "https://en.wikipedia.org/wiki/Kappabashi-dori", "description": "https://en.wikipedia.org/wiki/Kappabashi-dori", "hours": "https://www.kappabashi.or.jp/", "station": "https://www.kappabashi.or.jp/", "lat": "https://en.wikipedia.org/wiki/Kappabashi-dori", "lng": "https://en.wikipedia.org/wiki/Kappabashi-dori", "address": "https://www.kappabashi.or.jp/"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/e/e4/Kappabashi-dori_streetcorner_%28Kitchen_town_-_southern_end%29_Tokyo_Japan.jpg", "credit": "Basile Morin", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Kappabashi-dori_streetcorner_(Kitchen_town_-_southern_end)_Tokyo_Japan.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:shitamachi-museum', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Shitamachi Museum', 'museum', 'A nostalgic museum depicting life in the historic ''shitamachi'' flatlands of Tokyo, featuring reconstructed merchant shops, workshops, and Edo-period relics.', '[{"text": "Take off your shoes to step into the reconstructed merchant homes and interact with the nostalgic Shitamachi games and antique household items.", "source_url": "https://www.taitocity.net/zaidan/shitamachi/"}]'::jsonb, '9:30 AM - 4:30 PM (Closed Mondays)', 'known', 'Ueno-okachimachi Station', null, 35.7102, 139.7726, '2-1 Uenokoen, Taito City, Tokyo', null, null, null, '{}', '{"https://www.taitocity.net/zaidan/shitamachi/","https://ja.wikipedia.org/wiki/%E4%B8%8B%E7%94%AA%E9%A2%A8%E4%BF%97%E8%B3%87%E6%96%99%E9%A4%A8"}', '{"name": "https://ja.wikipedia.org/wiki/%E4%B8%8B%E7%94%AA%E9%A2%A8%E4%BF%97%E8%B3%87%E6%96%99%E9%A4%A8", "description": "https://ja.wikipedia.org/wiki/%E4%B8%8B%E7%94%AA%E9%A2%A8%E4%BF%97%E8%B3%87%E6%96%99%E9%A4%A8", "hours": "https://www.taitocity.net/zaidan/shitamachi/", "station": "https://www.taitocity.net/zaidan/shitamachi/", "lat": "https://ja.wikipedia.org/wiki/%E4%B8%8B%E7%94%AA%E9%A2%A8%E4%BF%97%E8%B3%87%E6%96%99%E9%A4%A8", "lng": "https://ja.wikipedia.org/wiki/%E4%B8%8B%E7%94%AA%E9%A2%A8%E4%BF%97%E8%B3%87%E6%96%99%E9%A4%A8", "address": "https://www.taitocity.net/zaidan/shitamachi/"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/e/ef/Shitamachi-museum-ueno-japan.jpg", "credit": "Tarourashima", "license": "Public domain", "source_url": "https://commons.wikimedia.org/wiki/File:Shitamachi-museum-ueno-japan.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:asakusa-culture-tourist-information-center', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Asakusa Culture Tourist Information Center', 'viewpoint', 'An architecturally striking multi-story wooden tourist center designed by Kengo Kuma, offering helpful services and a stunning 8th-floor observation deck.', '[{"text": "Head straight up to the 8th floor for a free, unobstructed bird''s-eye view of Nakamise-dori, Kaminarimon, and the Tokyo Skytree.", "source_url": "https://www.city.taito.lg.jp/index/bunka_kanko/oyakudachi/kankocenter/"}]'::jsonb, '9:00 AM - 8:00 PM (Observation deck open until 10:00 PM)', 'known', 'Asakusa Station', null, 35.710694, 139.7965, '2-18-9 Kaminarimon, Taito City, Tokyo', null, null, null, '{}', '{"https://www.city.taito.lg.jp/index/bunka_kanko/oyakudachi/kankocenter/","https://en.wikipedia.org/wiki/Asakusa_Culture_Tourist_Information_Center"}', '{"name": "https://en.wikipedia.org/wiki/Asakusa_Culture_Tourist_Information_Center", "description": "https://en.wikipedia.org/wiki/Asakusa_Culture_Tourist_Information_Center", "hours": "https://www.city.taito.lg.jp/index/bunka_kanko/oyakudachi/kankocenter/", "station": "https://www.city.taito.lg.jp/index/bunka_kanko/oyakudachi/kankocenter/", "lat": "https://en.wikipedia.org/wiki/Asakusa_Culture_Tourist_Information_Center", "lng": "https://en.wikipedia.org/wiki/Asakusa_Culture_Tourist_Information_Center", "address": "https://en.wikipedia.org/wiki/Asakusa_Culture_Tourist_Information_Center"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/5/5b/Asakusa_Culture_Tourist_Information_Center_2016.jpg", "credit": "Kakidai", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Asakusa_Culture_Tourist_Information_Center_2016.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:ueno-t-sh-g-shrine', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Ueno Tōshō-gū Shrine', 'shrine', 'A rare, surviving Edo-period Shinto shrine dedicated to Tokugawa Ieyasu, adorned with magnificent gold leaf carvings and hundreds of bronze lanterns.', '[{"text": "Visit the shrine during the winter or spring to see the beautiful peony garden (Peony Garden Ueno Toshogu), featuring rare floral displays.", "source_url": "http://www.uenotoshogu.com/en/"}]'::jsonb, '9:00 AM - 4:30 PM (October to February: 9:00 AM - 4:00 PM)', 'known', 'Ueno Station', null, 35.715361, 139.770583, '9-88 Uenokoen, Taito City, Tokyo', null, null, null, '{}', '{"http://www.uenotoshogu.com/","https://en.wikipedia.org/wiki/Ueno_T%C5%8Dsh%C5%AB-g%C5%AB"}', '{"name": "https://en.wikipedia.org/wiki/Ueno_T%C5%8Dsh%C5%AB-g%C5%AB", "description": "https://en.wikipedia.org/wiki/Ueno_T%C5%8Dsh%C5%AB-g%C5%AB", "hours": "http://www.uenotoshogu.com/en/", "station": "http://www.uenotoshogu.com/en/", "lat": "https://en.wikipedia.org/wiki/Ueno_T%C5%8Dsh%C5%AB-g%C5%AB", "lng": "https://en.wikipedia.org/wiki/Ueno_T%C5%8Dsh%C5%AB-g%C5%AB", "address": "http://www.uenotoshogu.com/en/"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/d/df/Toshogu_Shrine_06_%2815567282757%29.jpg", "credit": "Joe Mabel", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Toshogu_Shrine_06_(15567282757).jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:shinobazu-pond', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Shinobazu Pond', 'park', 'A beautiful, natural pond in Ueno Park famous for its dense summer lotus blooms, waterfowl, and the hexagonal Bentendo temple on its center island.', '[{"text": "Rent a whimsical swan pedal boat on the southern pond section for a fun and leisurely cruise with views of the Ueno skyline.", "source_url": "https://www.tokyo-park.or.jp/park/format/index038.html"}]'::jsonb, 'Open 24 hours (Boat rentals: 9:00 AM - 5:00 PM)', 'known', 'Ueno Station', null, 35.711389, 139.77, '5-20 Uenokoen, Taito City, Tokyo', null, null, null, '{}', '{"https://www.tokyo-park.or.jp/park/format/index038.html","https://en.wikipedia.org/wiki/Shinobazu_Pond"}', '{"name": "https://en.wikipedia.org/wiki/Shinobazu_Pond", "description": "https://en.wikipedia.org/wiki/Shinobazu_Pond", "hours": "https://www.tokyo-park.or.jp/park/format/index038.html", "station": "https://www.tokyo-park.or.jp/park/format/index038.html", "lat": "https://en.wikipedia.org/wiki/Shinobazu_Pond", "lng": "https://en.wikipedia.org/wiki/Shinobazu_Pond", "address": "https://en.wikipedia.org/wiki/Shinobazu_Pond"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/e/ea/%E4%B8%8D%E5%BF%8D%E6%B1%A0_-_panoramio.jpg", "credit": "Kurofune", "license": "CC BY 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:%E4%B8%8D%E5%BF%8D%E6%B1%A0_-_panoramio.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:ky-iwasaki-tei-garden', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Kyū-Iwasaki-tei Garden', 'attraction', 'A unique park containing the exquisite late-19th-century residential estates of the Mitsubishi clan, displaying a mix of Western and traditional Japanese architecture.', '[{"text": "Tour the inside of the Western-style mansion to admire the incredibly detailed Jacobean plasterwork and rare English hand-painted tile stoves.", "source_url": "https://www.tokyo-park.or.jp/park/format/index037.html"}]'::jsonb, '9:00 AM - 5:00 PM (Closed Dec 29 - Jan 3)', 'known', 'Yushima Station', null, 35.709722, 139.767778, '1-3-45 Ikenohata, Taito City, Tokyo', null, null, null, '{}', '{"https://www.tokyo-park.or.jp/park/format/index037.html","https://en.wikipedia.org/wiki/Ky%C5%AB-Iwasaki-tei_Garden"}', '{"name": "https://en.wikipedia.org/wiki/Ky%C5%AB-Iwasaki-tei_Garden", "description": "https://en.wikipedia.org/wiki/Ky%C5%AB-Iwasaki-tei_Garden", "hours": "https://www.tokyo-park.or.jp/park/format/index037.html", "station": "https://www.tokyo-park.or.jp/park/format/index037.html", "lat": "https://en.wikipedia.org/wiki/Ky%C5%AB-Iwasaki-tei_Garden", "lng": "https://en.wikipedia.org/wiki/Ky%C5%AB-Iwasaki-tei_Garden", "address": "https://www.tokyo-park.or.jp/park/format/index037.html"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/a/ab/Former_Iwasaki_Family_House_and_Garden_2010.jpg", "credit": "Wiiii", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Former_Iwasaki_Family_House_and_Garden_2010.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:tsubame-yu', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Tsubame-yu', 'bath', 'A historic public bathhouse (sento) in Ueno, famous for its morning hours and a rock bath mountain registered as a National Tangible Cultural Property.', '[{"text": "Experience a traditional morning soak, but be prepared as the waters of this historic sento are famously hot.", "source_url": "https://ja.wikipedia.org/wiki/%E7%85%92%E6%B1%80"}]'::jsonb, '6:00 AM - 8:00 PM (Closed Mondays)', 'known', 'Okachimachi Station', null, 35.705472, 139.772889, '3-14-5 Ueno, Taito City, Tokyo', null, null, null, '{}', '{"https://ja.wikipedia.org/wiki/%E7%85%92%E6%B1%80","https://www.sentou.or.jp/"}', '{"name": "https://ja.wikipedia.org/wiki/%E7%85%92%E6%B1%80", "description": "https://ja.wikipedia.org/wiki/%E7%85%92%E6%B1%80", "hours": "https://ja.wikipedia.org/wiki/%E7%85%92%E6%B1%80", "station": "https://ja.wikipedia.org/wiki/%E7%85%92%E6%B1%80", "lat": "https://ja.wikipedia.org/wiki/%E7%85%92%E6%B1%80", "lng": "https://ja.wikipedia.org/wiki/%E7%85%92%E6%B1%80", "address": "https://ja.wikipedia.org/wiki/%E7%85%92%E6%B1%80"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/7/7b/Tsubameyu_01.jpg", "credit": "Thirteen-fri", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Tsubameyu_01.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'name:tokyo:taito:hanayashiki', 'Kanto', 'Tokyo', 'Taito', 'JP', 'Hanayashiki', 'attraction', 'Dating back to 1853, Hanayashiki is celebrated as Japan''s oldest amusement park, featuring a charming retro ambiance and a classic steel roller coaster.', '[{"text": "Ride the oldest surviving steel roller coaster in Japan, which has been thrilling visitors since 1953 as it zips past retro wooden buildings.", "source_url": "https://www.hanayashiki.net/"}]'::jsonb, '10:00 AM - 6:00 PM (varies by season)', 'known', 'Asakusa Station', null, 35.715497, 139.794689, '2-28-1 Asakusa, Taito City, Tokyo', null, null, null, '{}', '{"https://www.hanayashiki.net/","https://en.wikipedia.org/wiki/Hanayashiki"}', '{"name": "https://en.wikipedia.org/wiki/Hanayashiki", "description": "https://en.wikipedia.org/wiki/Hanayashiki", "hours": "https://www.hanayashiki.net/", "station": "https://www.hanayashiki.net/", "lat": "https://en.wikipedia.org/wiki/Hanayashiki", "lng": "https://en.wikipedia.org/wiki/Hanayashiki", "address": "https://en.wikipedia.org/wiki/Hanayashiki"}'::jsonb, null, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/2/29/Hanayashiki-fromair-oct6-2015.jpg", "credit": "Nesnad", "license": "CC BY 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Hanayashiki-fromair-oct6-2015.jpg", "is_exact_place": true, "provider": "wikimedia"}]'::jsonb, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00')
