  ('jp-tokyo-2026-07-15', 'JP', 'Tokyo', 'Shibuya', 'Harajuku Crepes', 'Sweet and savory paper-wrapped crepes filled with whipped cream, ice cream, fresh fruit, and various sweet toppings, popularized in Harajuku''s Takeshita Street in the late 1970s.', '{"https://www.gotokyo.org/en/destinations/western-tokyo/harajuku/index.html","https://www.marion.co.jp/"}', '{"Cat Street","Miyashita Park","Shibuya PARCO"}', 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'JP', 'Tokyo', 'Shinjuku', 'Yakitori (Grilled Chicken Skewers)', 'Succulent skewers of chicken grilled over charcoal, seasoned with salt or savory tare sauce, and served in Shinjuku''s atmospheric post-war alleyways.', '{"http://shinjuku-omoide.com/english/index.html"}', '{"Omoide Yokocho"}', 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00'),
  ('jp-tokyo-2026-07-15', 'JP', 'Tokyo', 'Taito', 'Ningyoyaki', 'An iconic, sweet baked doll sponge cake filled with sweet red bean paste (anko), traditionally molded into the shapes of Asakusa''s landmark five-story pagodas, giant paper lanterns, and deities.', '{"https://ja.wikipedia.org/wiki/%E4%BA%BA%E5%BD%A2%E7%83%BC","https://www.asakusa-nakamise.jp/"}', '{"Nakamise Shopping Street"}', 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-15T01:01:38.172820+00:00')
